<body><main>
  <div class="top"><div><h1>明星志愿3 · 辅助助手</h1><div class="author">作者：<b>小满</b></div></div><div class="top-side"><div class="date" id="date">游戏日期 等待游戏…</div><div class="window-tools"><button id="topmostButton" onclick="toggleTopmost()" title="让程序窗口保持在其他窗口上方">📌 窗口置顶</button><span>字号</span><button data-font="small" onclick="setFontSize('small')">小</button><button data-font="medium" onclick="setFontSize('medium')">中</button><button data-font="large" onclick="setFontSize('large')">大</button></div></div></div>
  <div class="bar"><span class="dot" id="dot"></span><span class="status" id="status">正在连接 Stardom3.exe</span></div>
  <nav class="tabs"><button class="tab active" data-page="artists">艺人属性<span class="count" id="artistCount">0</span></button><button class="tab" data-page="company">公司概览<span class="count" id="itemCount">0</span></button><button class="tab" data-page="notices">通告<span class="count" id="noticeCount">0</span></button><button class="tab" data-page="reminders">本周提醒<span class="count" id="reminderCount">0</span></button><button class="tab" data-page="events">剧情<span class="count" id="eventCount">0</span></button></nav>
  <div class="card artist-toolbar" id="artistTools"><input id="search" placeholder="搜索艺人姓名或ID"><select id="scope"><option value="signed">仅签约艺人</option><option value="all">全部艺人</option></select></div>
  <div id="content"><div class="card"><div class="empty">请启动游戏并读取一个存档</div></div></div>
  <footer>作者：小满 · 数据每秒刷新 · 本工具仅申请 PROCESS_VM_READ 权限</footer>
</main>
<script>
const labels=[['favorability','好感度'],['acting','演技'],['eloquence','口才'],['singing','歌艺'],['fame','名气'],['demeanor','仪态'],['dynamics','动感'],['stamina','体能'],['intelligence','才智'],['confidence','自信'],['stress','压力'],['fatigue','疲劳'],['rebellious','叛逆'],['sexy','性感'],['affinity','亲和'],['popularity','人气'],['exposure','曝光'],['success','成功']];
let state=null,catalog=null,page='artists',eventArtist='',eventStory='all',eventQuery='',eventProgressFilter='all',showMissedEvents=true,eventFavoritesOnly=false,noticeCategory='all',activeProgressSlot='slot1',reminderPrereqMode='ready';const openNoticeCards=new Set(),completedEvents=new Set(),missedStories=new Set(),favoriteSubjects=new Set();const $=id=>document.getElementById(id),PROGRESS_KEY='stardom3-event-progress-v1',MISSED_KEY='stardom3-event-missed-v1',SLOTS_KEY='stardom3-event-progress-slots-v1',FAVORITES_KEY='stardom3-event-favorite-subjects-v1';$('search').oninput=render;$('scope').onchange=render;
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{page=b.dataset.page;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===b));$('artistTools').style.display=page==='artists'?'flex':'none';render()});
function setFontSize(size){const value=['small','medium','large'].includes(size)?size:'medium';document.body.dataset.font=value;document.querySelectorAll('[data-font]').forEach(b=>b.classList.toggle('active',b.dataset.font===value));try{localStorage.setItem('stardom3-font-size',value)}catch{}}
try{setFontSize(localStorage.getItem('stardom3-font-size')||'medium')}catch{setFontSize('medium')}
function setTopmostState(value){const button=$('topmostButton');if(!button)return;button.classList.toggle('active',!!value);button.textContent=value?'📌 已置顶':'📌 窗口置顶';button.setAttribute('aria-pressed',value?'true':'false')}
function toggleTopmost(){if(window.chrome?.webview)window.chrome.webview.postMessage({action:'toggleTopmost'});else alert('窗口置顶功能仅在桌面版程序中可用')}
if(window.chrome?.webview)window.chrome.webview.addEventListener('message',e=>{if(e.data?.action==='topmostChanged')setTopmostState(e.data.value)});
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function loadProgress(){try{const saved=JSON.parse(localStorage.getItem(PROGRESS_KEY)||'[]');completedEvents.clear();if(Array.isArray(saved))saved.map(String).filter(x=>x.split('::').length===3).forEach(x=>completedEvents.add(x));persistProgress()}catch{completedEvents.clear()}}
function persistProgress(){try{localStorage.setItem(PROGRESS_KEY,JSON.stringify([...completedEvents]))}catch{}}
function loadMissedStories(){try{const saved=JSON.parse(localStorage.getItem(MISSED_KEY)||'[]');missedStories.clear();if(Array.isArray(saved))saved.map(String).filter(x=>x.split('::').length===2).forEach(x=>missedStories.add(x));persistMissedStories()}catch{missedStories.clear()}}
function persistMissedStories(){try{localStorage.setItem(MISSED_KEY,JSON.stringify([...missedStories]))}catch{}}
function loadFavoriteSubjects(){try{const saved=JSON.parse(localStorage.getItem(FAVORITES_KEY)||'[]');favoriteSubjects.clear();if(Array.isArray(saved))saved.map(String).filter(Boolean).forEach(x=>favoriteSubjects.add(x))}catch{favoriteSubjects.clear()}}
function persistFavoriteSubjects(){try{localStorage.setItem(FAVORITES_KEY,JSON.stringify([...favoriteSubjects]))}catch{}}
function loadProgressSlots(){try{const value=JSON.parse(localStorage.getItem(SLOTS_KEY)||'{}');return value&&typeof value==='object'&&!Array.isArray(value)?value:{}}catch{return {}}}
function persistProgressSlots(slots){try{localStorage.setItem(SLOTS_KEY,JSON.stringify(slots));return true}catch{return false}}
function eventProgressKey(subject,section,id){return `${encodeURIComponent(subject)}::${encodeURIComponent(section)}::${encodeURIComponent(id)}`}
function storyProgressKey(subject,section){return `${encodeURIComponent(subject)}::${encodeURIComponent(section)}`}
function catalogStoryItems(subject,section,fallback=[]){const groups=[...(catalog?.artists||[]),...(catalog?.specialEvents||[])],owner=groups.find(x=>x.name===subject),items=(owner?.events||[]).filter(e=>e.section===section);return items.length?items:fallback}
function orderedStoryKeys(subject,section,fallback=[]){return catalogStoryItems(subject,section,fallback).map(e=>eventProgressKey(subject,e.section,e.id))}
function prerequisiteFor(e){const current=eventProgressKey(e.artist,e.section,e.id),keys=orderedStoryKeys(e.artist,e.section,[e]),index=keys.indexOf(current),required=index>0?keys.slice(0,index):[],done=required.filter(key=>completedEvents.has(key)).length;return {current,keys,required,done,satisfied:done===required.length,isCompleted:completedEvents.has(current)}}
function slotLabel(id,slot){const number=id.replace('slot','');return slot?.name?`${number} · ${slot.name}`:`槽位 ${number}（空）`}
function progressSlotPanel(){const slots=loadProgressSlots(),slot=slots[activeProgressSlot],hasMarks=completedEvents.size||missedStories.size;return `<section class="card progress-slots"><strong>剧情进度存档</strong><select id="progressSlot" aria-label="选择剧情进度存档槽位">${[1,2,3,4,5].map(n=>{const id=`slot${n}`;return `<option value="${id}" ${id===activeProgressSlot?'selected':''}>${esc(slotLabel(id,slots[id]))}</option>`}).join('')}</select><input id="progressSlotName" maxlength="30" value="${esc(slot?.name||'')}" placeholder="输入槽位名称"><button id="saveProgressSlot">保存当前标记</button><button id="loadProgressSlot" ${slot?'':'disabled'}>读取</button><button id="deleteProgressSlot" class="danger" ${slot?'':'disabled'}>删除槽位</button><button id="clearProgress" class="danger" ${hasMarks?'':'disabled'}>清空当前标记</button><span class="spacer"></span><span class="progress-message" id="progressMessage">当前已完成 ${completedEvents.size} 个节点 · 已错过 ${missedStories.size} 段剧情${slot?.savedAt?` · 此槽位保存于 ${esc(new Date(slot.savedAt).toLocaleString('zh-CN'))}`:''}</span></section>`}
