 const refreshEventResults=()=>{const found=filterItems();document.querySelector('.event-catalog').innerHTML=renderStoryGroups(found,artist?.events||[]);$('eventResultCount').textContent=`当前 ${found.length} 条 · ${totalLabel}`;wireCompletionControls()};
