 $('eventArtist').onchange=e=>{eventArtist=e.target.value;eventStory='all';renderEvents()};$('favoriteSubject').onclick=()=>{if(!eventArtist)return;if(favoriteSubjects.has(eventArtist))favoriteSubjects.delete(eventArtist);else favoriteSubjects.add(eventArtist);persistFavoriteSubjects();renderEvents()};$('favoriteSubjectsOnly').onclick=()=>{eventFavoritesOnly=!eventFavoritesOnly;eventStory='all';renderEvents()};$('eventStory').onchange=e=>{eventStory=e.target.value;refreshEventResults()};$('eventProgressFilter').onchange=e=>{eventProgressFilter=e.target.value;renderEvents()};$('showMissedEvents').onchange=e=>{showMissedEvents=e.target.checked;renderEvents()};$('eventSearch').oninput=e=>{eventQuery=e.target.value;refreshEventResults()}
}
async function loadCatalog(){try{const r=await fetch('/api/events',{cache:'no-store'});catalog=await r.json();$('eventCount').textContent=catalog.eventCount||0;if(page==='events')render()}catch{catalog=null}}
function reminderSignature(value){return `${value?.date||''}|${(value?.artists||[]).filter(a=>a.isSigned).map(a=>a.id).join(',')}|${(value?.weeklyEvents?.events||[]).map(e=>`${e.artist}:${e.id}:${e.isRecruitment}:${e.isSpecialEvent}`).join(',')}`}
async function poll(){try{const previous=reminderSignature(state),r=await fetch('/api/state',{cache:'no-store'});state=await r.json();$('dot').className='dot '+(state.connected?'on':'');$('status').textContent=state.loaded?`已连接游戏（PID ${state.processId}）· 数据实时刷新中`:state.message;$('date').innerHTML=state.date?`游戏日期 ${state.date}<small>${state.weekday}</small>`:'游戏日期 等待游戏…';$('artistCount').textContent=state.artists?.filter(a=>a.isSigned).length||0;$('itemCount').textContent=state.company?.items?.length||0;$('noticeCount').textContent=(state.currentNotices?.length||0)+(state.recruitingNotices?.length||0);$('reminderCount').textContent=state.weeklyEvents?.eventCount||0;$('eventCount').textContent=catalog?.eventCount||0;const changed=previous!==reminderSignature(state);if(page==='reminders'?changed:page!=='events')render()}catch{$('dot').className='dot';$('status').textContent='助手服务连接中断'}setTimeout(poll,1000)}loadCatalog();poll();
</script></body></html>
""";
